+const chargeTimeout = 2 * time.Second
+
+func (c *Client) Charge(ctx context.Context, id string, kop int64) error {
+	ctx, cancel := context.WithTimeout(ctx, chargeTimeout)
+
+	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.url(id), body(kop))
 	if err != nil {
 		return fmt.Errorf("build request: %w", err)
 	}

 	resp, err := c.http.Do(req)
 	if err != nil {
 		return fmt.Errorf("charge %s: %w", id, err)
 	}
 	defer resp.Body.Close()

+	if resp.StatusCode != http.StatusOK {
+		return fmt.Errorf("charge %s: status %d", id, resp.StatusCode)
+	}
+
+	cancel()
 	return nil
 }
